var MAINTAINER_PERMS = /* @__PURE__ */ new Set(["admin", "write", "maintain"]);
async function isMaintainer(octokit, owner, repo, username) {
  try {
    const r2 = await octokit.rest.repos.getCollaboratorPermissionLevel({
      owner,
      repo,
      username
    });
    return MAINTAINER_PERMS.has(r2.data.permission) || MAINTAINER_PERMS.has(r2.data.role_name ?? "");
  } catch {
    return false;
  }
}
async function runSlopCommand(octokit, owner, repo, issueNumber, commenter, body) {
  const m2 = body.match(/^\s*\/slop\s+(approve|reject|false-positive|fp)\b/im);
  if (!m2) return null;
  const cmd = m2[1].toLowerCase();
  if (!await isMaintainer(octokit, owner, repo, commenter)) {
    await octokit.rest.issues.createComment({
      owner,
      repo,
      issue_number: issueNumber,
      body: `@${commenter} only maintainers (write access) can run SlopGuard commands.`
    }).catch(() => void 0);
    return null;
  }
  const policy = await loadPolicy(octokit, owner, repo);
  const qLabel = policy.labels.quarantine;
  if (cmd === "approve") {
    await removeLabel(octokit, owner, repo, issueNumber, qLabel);
    await removeLabel(
      octokit,
      owner,
      repo,
      issueNumber,
      policy.labels.high_confidence
    );
    await ensureLabel(
      octokit,
      owner,
      repo,
      policy.labels.approved,
      LABEL_COLORS.approved,
      "Cleared by maintainer"
    );
    await addLabels(octokit, owner, repo, issueNumber, [
      policy.labels.approved
    ]);
    await octokit.rest.issues.createComment({
      owner,
      repo,
      issue_number: issueNumber,
      body: `\u2705 Quarantine cleared by @${commenter}. Thanks for reviewing!`
    });
    return { outcome: "cleared", policy };
  }
  if (cmd === "reject") {
    await octokit.rest.issues.createComment({
      owner,
      repo,
      issue_number: issueNumber,
      body: `\u274C Closed as AI slop by @${commenter} (explicit maintainer action).`
    });
    await octokit.rest.issues.update({
      owner,
      repo,
      issue_number: issueNumber,
      state: "closed",
      state_reason: "not_planned"
    });
    return { outcome: "confirmed", policy };
  }
  await createFeedbackIssue(
    octokit,
    owner,
    repo,
    policy,
    issueNumber,
    commenter
  );
  await removeLabel(octokit, owner, repo, issueNumber, qLabel);
  await octokit.rest.issues.createComment({
    owner,
    repo,
    issue_number: issueNumber,
    body: `\u{1F64F} Marked as false positive by @${commenter}. Quarantine cleared and a tuning issue was opened. Sorry for the noise!`
  });
  return { outcome: "cleared", policy };
}

// action/main.ts
async function main() {
  const token = process.env.INPUT_TOKEN || process.env.GITHUB_TOKEN;
  if (!token) throw new Error("missing token input");
  const event = process.env.GITHUB_EVENT_NAME ?? "";
  let payload;
  try {
    payload = JSON.parse(
      readFileSync(process.env.GITHUB_EVENT_PATH ?? "", "utf8")
    );
  } catch (err) {
    throw new Error(`cannot read GITHUB_EVENT_PATH: ${err}`);
  }
  const octokit = new Octokit2({
    auth: token,
    baseUrl: process.env.GITHUB_API_URL
  });
  const owner = payload.repository.owner.login;
  const repo = payload.repository.name;
  if (event === "issue_comment") {
    if (payload.action !== "created" || payload.sender?.type === "Bot") return;
    await runSlopCommand(
      octokit,
      owner,
      repo,
      payload.issue.number,
      payload.comment.user?.login ?? payload.sender.login,
      payload.comment.body ?? ""
    );
    return;
  }
  if (!["opened", "reopened", "synchronize"].includes(payload.action)) return;
  let input;
  if (event === "pull_request" || event === "pull_request_target") {
    input = await buildPullRequestInput(
      octokit,
      payload.repository,
      payload.pull_request
    );
  } else if (event === "issues") {
    input = buildIssueInput(payload.repository, payload.issue);
  } else {
    console.log(`[slopguard] ignoring event ${event}`);
    return;
  }
  const policy = await loadPolicy(octokit, owner, repo);
  if (!policy.enabled) return;
  if (input.kind === "pull_request" && !policy.scan.pull_requests) return;
  if (input.kind === "issue" && !policy.scan.issues) return;
  if (isAllowlisted(policy, input)) {
    console.log(`[slopguard] allowlisted: ${input.repo}#${input.number}`);
    return;
  }
  const result = await analyzeSlop(input, toAgentPolicy(policy));
  const action = await applyVerdict(octokit, owner, repo, policy, input, result);
  console.log(
    `[slopguard] ${action} ${input.repo}#${input.number} (${result.score}, ${result.verdict})`
  );
  if (process.env.GITHUB_OUTPUT) {
    appendFileSync(
      process.env.GITHUB_OUTPUT,
      `score=${result.score}
verdict=${result.verdict}
quarantined=${action === "quarantined"}
`
    );
  }
}
main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
